mkdir -p /tmp/pw && cat > /tmp/pw/check.mjs <<'EOF'
import { chromium } from 'playwright';

const URL = 'http://127.0.0.1:5190/';
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const errors = [];
page.on('console', (m) => { if (m.type() === 'error' || m.type() === 'warning') errors.push(`${m.type()}: ${m.text()}`); });
page.on('pageerror', (e) => errors.push(`pageerror: ${e.message}`));
const results = {};

await page.goto(URL, { waitUntil: 'networkidle' });
await page.waitForSelector('.orders-table');
results.initialRows = await page.locator('.orders-table tbody tr.group-row').count();
results.initialDataRows = await page.locator('.orders-table tbody tr:not(.group-row)').count();
results.groupHeaders = await page.locator('.orders-table tr.group-row .g-label, .orders-table tr.group-row span').allInnerTexts().then(t => t.slice(0, 0));
results.groupLabels = await page.locator('.group-row .group-cell').allInnerTexts();
results.headers = await page.locator('.orders-table thead th').allInnerTexts();
await page.screenshot({ path: '/tmp/pw/home.png', fullPage: false });

// Sidebar collapse
const sidebar = page.locator('aside.sidebar');
results.sidebarWidthExpanded = (await sidebar.boundingBox()).width;
await page.locator('.sidebar-header button').click();
await page.waitForTimeout(350);
results.sidebarWidthCollapsed = (await sidebar.boundingBox()).width;
await page.screenshot({ path: '/tmp/pw/collapsed.png', fullPage: false });
await page.locator('.sidebar-header button').click();
await page.waitForTimeout(350);

// Selection: click row 1, shift-click row 3
const dataRows = page.locator('.orders-table tbody tr:not(.group-row)');
await dataRows.nth(0).locator('td').nth(1).click();
await dataRows.nth(2).locator('td').nth(1).click({ modifiers: ['Shift'] });
await page.waitForTimeout(100);
results.selectedSelectionCount = await page.locator('.is-selected').count();
results.selectedText = await page.locator('text=/Выбрано:/').first().innerText().catch(() => 'none');
// Checkbox click on a row
await dataRows.nth(5).locator('.cell-check label, .cell-check').first().click();
await page.waitForTimeout(100);
results.afterCheckboxClick = await page.locator('.is-selected').count();
results.selectedText2 = await page.locator('text=/Выбрано:/').first().innerText().catch(() => 'none');

// Column drag: move "Клиент" onto "Статус"
await page.locator('.orders-table thead th', { hasText: 'Клиент' }).dragTo(page.locator('.orders-table thead th', { hasText: 'Статус' }));
await page.waitForTimeout(100);
results.headersAfterDrag = await page.locator('.orders-table thead th').allInnerTexts();

// Keyboard column move: focus "Город", Alt+ArrowLeft
await page.locator('.orders-table thead th', { hasText: 'Город' }).focus();
await page.keyboard.press('Alt+ArrowLeft');
await page.waitForTimeout(100);
results.headersAfterKeyboard = await page.locator('.orders-table thead th').allInnerTexts();

// Collapse first group
const firstToggle = page.locator('.group-toggle').first();
const before = await dataRows.count();
await firstToggle.click();
await page.waitForTimeout(100);
