// @vitest-environment jsdom
import { afterEach, describe, expect, it } from 'vitest';
import { cleanup, fireEvent, render, within } from '@testing-library/react';
import { ThemeProvider } from '@gravity-ui/uikit';
import { App } from '../App';

afterEach(cleanup);

const dt = () => ({ setData: () => {}, effectAllowed: '', dropEffect: '' });

function setup() {
  const utils = render(<ThemeProvider theme="light"><App /></ThemeProvider>);
  const headers = () =>
    Array.from(document.querySelectorAll('.orders-table thead th .th-content')).map((n) => n.textContent);
  const dataRows = () => Array.from(document.querySelectorAll('.orders-table tbody tr:not(.group-row)'));
  const selectedCount = () => document.querySelectorAll('.orders-table tbody tr.is-selected').length;
  const headerCell = (title: string) =>
    Array.from(document.querySelectorAll('.orders-table thead th')).find((th) => th.textContent?.includes(title)) as HTMLElement;
  return { ...utils, headers, dataRows, selectedCount, headerCell };
}

describe('dashboard verification', () => {
  it('renders stats, sidebar, grouped table', () => {
    const t = setup();
    const nav = within(document.querySelector('nav')!);
    expect(nav.getByText('Главная')).toBeTruthy();
    expect(nav.getByText('Пользователи')).toBeTruthy();
    expect(nav.getByText('Заказы')).toBeTruthy();
    expect(nav.getByText('Настройки')).toBeTruthy();
    const tiles = Array.from(document.querySelectorAll('.stat-tile')).map((n) => n.textContent);
    console.log('TILES', JSON.stringify(tiles));
    const groups = Array.from(document.querySelectorAll('.group-cell')).map((n) => n.textContent);
    console.log('GROUPS', JSON.stringify(groups));
    expect(t.dataRows().length).toBe(120);
    console.log('HEADERS', JSON.stringify(t.headers()));
    expect(t.headers()).toEqual(['Номер', 'Клиент', 'Город', 'Позиции', 'Сумма', 'Статус', 'Дата']);
  });

  it('sidebar collapses to icons and persists', () => {
    const t = setup();
    const toggle = document.querySelector('.sidebar-header button') as HTMLButtonElement;
    fireEvent.click(toggle);
    expect(document.querySelector('aside.sidebar')!.className).toContain('is-collapsed');
    expect(document.querySelectorAll('.sidebar-item-label').length).toBe(0);
    expect(localStorage.getItem('admin.sidebar.collapsed')).toBe('1');
    expect(document.querySelector('.sidebar-item[aria-label="Заказы"]')).toBeTruthy();
    fireEvent.click(toggle);
    expect(document.querySelectorAll('.sidebar-item-label').length).toBe(4);
    expect(t).toBeTruthy();
  });

  it('row selection: click, shift-range, checkbox, header select-all', () => {
    const t = setup();
    const rows = t.dataRows();
    fireEvent.click(rows[0].querySelectorAll('td')[1]);
    expect(t.selectedCount()).toBe(1);
    fireEvent.click(rows[2].querySelectorAll('td')[1], { shiftKey: true });
    expect(t.selectedCount()).toBe(3);
    // checkbox click on row 5 (label/input path)
    const cb = rows[5].querySelector('.cell-check input') as HTMLInputElement;
    fireEvent.click(cb);
    expect(t.selectedCount()).toBe(4);
    // header checkbox -> select all visible
    const headerCb = document.querySelector('.orders-table thead .cell-check input') as HTMLInputElement;
    fireEvent.click(headerCb);
    const visible = t.dataRows().length;
    console.log('SELECT_ALL visible', visible, 'selected', t.selectedCount());
    expect(t.selectedCount()).toBe(visible);
    fireEvent.click(headerCb);
    expect(t.selectedCount()).toBe(0);
  });

  it('column drag reorders, and Alt+arrow reorders from keyboard', () => {
    const t = setup();
    const src = t.headerCell('Клиент');
    const dst = t.headerCell('Статус');
    fireEvent.dragStart(src, { dataTransfer: dt() });
    fireEvent.dragOver(dst, { dataTransfer: dt() });
    fireEvent.drop(dst, { dataTransfer: dt() });
    expect(t.headers()).toEqual(['Номер', 'Город', 'Позиции', 'Сумма', 'Статус', 'Клиент', 'Дата']);
    fireEvent.keyDown(t.headerCell('Город'), { key: 'ArrowLeft', altKey: true });
    expect(t.headers()).toEqual(['Город', 'Номер', 'Позиции', 'Сумма', 'Статус', 'Клиент', 'Дата']);
    // Data cells follow header order: first data cell text should be city of first order now
    const firstRowCells = t.dataRows()[0].querySelectorAll('td');
    console.log('FIRST_ROW_CELL1', firstRowCells[1].textContent, 'CELL2', firstRowCells[2].textContent);
    expect(firstRowCells[1].textContent).toMatch(/^(Москва|Санкт|Казань|Новосибирск|Екатеринбург|Нижний)/);
  });

  it('group collapse hides rows; group checkbox selects group; ungrouping shows flat list', () => {
    const t = setup();
    const before = t.dataRows().length;
    const firstToggle = document.querySelector('.group-toggle') as HTMLButtonElement;
    const groupName = firstToggle.getAttribute('aria-label');
    fireEvent.click(firstToggle);
    const after = t.dataRows().length;
    console.log('COLLAPSE', groupName, before, '->', after, 'expanded=', firstToggle.getAttribute('aria-expanded'));
    expect(after).toBeLessThan(before);
    expect(firstToggle.getAttribute('aria-expanded')).toBe('false');

    // group checkbox on the (still expanded) second group
    const groupCb = document.querySelectorAll('.group-row .cell-check input')[1] as HTMLInputElement;
    fireEvent.click(groupCb);
    const groupRowCount = document.querySelectorAll('.group-row')[1].nextElementSibling ? 1 : 0;
    console.log('GROUP_SELECT selected=', t.selectedCount(), 'groupRow', groupRowCount);
    expect(t.selectedCount()).toBeGreaterThan(0);

    fireEvent.click(within(document.querySelector('.table-actions')!).getByText('По статусу'));
    const flat = document.querySelectorAll('.orders-table tbody tr');
    console.log('FLAT_ROWS', flat.length, 'group rows', document.querySelectorAll('.group-row').length);
    expect(document.querySelectorAll('.group-row').length).toBe(0);
    expect(flat.length).toBe(120);
  });

  it('navigates to the Orders page', () => {
    setup();
    fireEvent.click(within(document.querySelector('nav')!).getByText('Заказы'));
    expect(document.querySelector('h1.page-title')!.textContent).toBe('Заказы');
    expect(document.querySelector('.orders-table')).toBeTruthy();
    fireEvent.click(within(document.querySelector('nav')!).getByText('Настройки'));
    expect(document.querySelector('h1.page-title')!.textContent).toBe('Настройки');
  });
});
EOF
